  "onboarding.templates.wiseDiscountHint":
    "Un paiement via Stripe vous coûte les frais de traitement de Stripe, facturés par Stripe au tarif qu'il fixe pour votre pays. Un virement Wise ne passe jamais par Stripe : il ne vous coûte aucuns frais de traitement, vous pouvez donc répercuter cette économie sur votre élève. Par prudence, nous calculons la remise suggérée avec notre propre estimation délibérément haute — {rate} % plus une petite commission fixe, ce qui correspond à une carte internationale avec conversion de devise — de sorte que la plupart des paiements vous coûtent moins que prévu et que le prix Wise ne vous désavantage jamais. Les deux prix restent modifiables.",
