  "web.settings.bookingPageLocale.savedMessage": "Enregistré.",
  "web.settings.autoSurfaceMaterials.label": "Afficher les matériels de son niveau à chaque cours",
  "web.settings.autoSurfaceMaterials.hint":
    "À chaque cours réservé, affichez les matériels de votre bibliothèque correspondant au niveau de l'élève — c'est toujours vous qui décidez d'en joindre un.",
  "web.settings.autoRecordClasses.label": "Enregistrer mes cours automatiquement",
  "web.settings.autoRecordClasses.hint":
    "L'enregistrement démarre tout seul dès que votre élève et vous êtes dans l'appel, pour que vous n'ayez pas à y penser. Votre élève et vous voyez tous les deux l'indicateur d'enregistrement, et vous pouvez l'arrêter à tout moment. Le fait d'analyser la voix d'un élève pour en tirer des observations d'apprentissage est une autorisation distincte, que vous enregistrez pour chaque élève.",
  "web.settings.materialStyle.title": "Style des matériels IA",
  "web.settings.materialStyle.subtitle":
    "Ajustez la façon dont l'IA rédige vos matériels. S'applique à tous les matériels que vous générez — contenu de cours et bibliothèque.",
