  "web.settings.bookingPage.video.scriptBeat1":
    "Votre nom et qui vous aidez \u2014 soyez pr\u00e9cise\u00a0: \u00abdes adultes qui ont \u00e9tudi\u00e9 il y a des ann\u00e9es et qui se bloquent d\u00e8s qu\u2019il faut parler\u00bb.",
