  "web.settings.payments.saveBankAccount": "Enregistrer le compte bancaire",
  "web.settings.payments.feesTitle": "Votre forfait et les frais de Stripe sont distincts",
  "web.settings.payments.feesBody":
    "Vous payez SpiralClass pour le logiciel. Vous payez Stripe pour le traitement des paiements effectués via Stripe — il facture ces frais sur votre propre compte, au tarif qu'il fixe pour votre pays et selon le moyen utilisé par votre élève, cartes comme options locales. SpiralClass n'en reçoit aucune part et ne prélève aucune commission sur ce que vous gagnez en enseignant. Un virement Wise ne passe jamais par Stripe et ne supporte aucuns frais Stripe.",
  "web.settings.payments.feesStripeLink": "Voir les tarifs de Stripe",
  "web.settings.payments.introStripeAndWise":
    "Connectez Stripe pour accepter les paiements par carte et/ou Wise pour les virements. Vos élèves choisissent au moment du paiement.",
  "web.settings.payments.introWiseOnly":
    "Vos élèves vous paieront via Wise. Nous envoyons une référence unique ; vous confirmez la réception.",
  "web.settings.payments.connectedNotice":
    "Compte lié à Stripe. Si Stripe demande encore des documents, terminez la démarche depuis le bouton ci-dessous.",
  "web.settings.payments.disconnectedNotice":
    "Vous avez déconnecté Stripe. Vos élèves ne pourront pas acheter de forfaits tant que vous ne vous reconnectez pas.",
  "web.settings.payments.incompleteNotice":
    "Vous n'avez pas terminé la vérification Stripe. Réessayez quand vous voulez.",
  "web.settings.payments.actionNeeded": "Stripe a besoin de plus d'informations : {reason}",
  "web.settings.payments.wiseSavedNotice": "Paramètres Wise enregistrés.",
  "web.settings.payments.stripeCardHelp":
    "Votre élève vous paie directement. L'argent arrive sur votre propre compte Stripe et Stripe le verse à votre banque — nous ne le détenons jamais et n'en prélevons aucune part. Stripe vous facture ses propres frais de traitement sur chaque paiement, au tarif qu'il fixe pour votre pays et selon le moyen choisi par votre élève, et gère les remboursements et les litiges.",
  "web.settings.payments.continueVerification": "Poursuivre la vérification dans Stripe",
  "web.settings.payments.disconnect": "Déconnecter",
  "web.settings.payments.stripeOnboardingHelp":
    "Nous vous emmènerons sur Stripe pour vérifier votre identité et lier votre compte bancaire. Le processus prend quelques minutes.",
  "web.settings.payments.connectStripe": "Connecter Stripe",
  "web.settings.payments.countryUnsupportedHelp":
    "Les paiements par carte via Stripe ne sont pas encore disponibles dans votre pays. En attendant, configurez Wise ci-dessous pour être payé — vos élèves vous virent directement.",
  "web.settings.payments.wiseCardHelp":
    "Votre élève paie directement sur votre compte Wise. L'argent ne passe jamais par Stripe, il n'y a donc aucuns frais de traitement Stripe. Nous lui envoyons le paiement avec une référence unique ; vous confirmez la réception depuis le panneau des paiements. Wise ou votre banque peuvent toutefois vous facturer la réception de l'argent.",
