    "Stripe n'est pas encore disponible pour les paiements par carte. En attendant, configurez Wise.",
  "web.settings.payments.error.countryUnsupported":
    "Les paiements par carte via Stripe ne sont pas encore disponibles dans votre pays. Utilisez Wise pour être payé en attendant.",
