    "Nous n'arrivons pas à accéder au compte Stripe lié à votre profil : il n'a pas été créé par SpiralClass, nous ne pouvons donc pas l'utiliser. Contactez le support et nous le relierons. En attendant, Wise et le virement bancaire continuent de fonctionner.",
