    "Planning, paiements Stripe et rappels automatiques pour les enseignants de toute matière.",
  "web.landing.meta.title": "SpiralClass — Agenda, paiements et rappels pour les enseignants",
  "web.landing.meta.description":
    "Partagez votre lien de réservation, encaissez via Stripe ou Wise, et envoyez des rappels automatiques à vos élèves. Commencez avec {days} jours de Pro gratuits, sans carte.",
  "web.layout.meta.description":
    "SpiralClass organise vos cours, vos paiements et vos rappels pour que vous puissiez enseigner n'importe quelle matière sans la charge mentale.",
  "web.pricing.meta.title": "Tarifs",
  "web.pricing.meta.description":
    "Formule gratuite à vie et Pro à {monthly} par mois. Essayez Pro pendant {days} jours sans carte — SpiralClass ne prélève jamais une part de ce que vos élèves vous paient.",
  "web.help.meta.title": "Centre d'aide",
  "web.help.meta.description":
    "Comment fonctionnent les paiements, les formules et les réservations sur SpiralClass.",
  "web.terms.meta.title": "Conditions d'utilisation",
  "web.terms.meta.description": "Les conditions générales d'utilisation d'SpiralClass.",
  "web.privacyNotice.meta.title": "Politique de confidentialité",
  "web.privacyNotice.meta.description":
    "Comment SpiralClass collecte, utilise et protège vos données personnelles, conformément au RGPD du Royaume-Uni.",
  "web.about.eyebrow": "Fondée par une enseignante et un développeur",
  "web.about.headline": "Pourquoi SpiralClass existe",
  "web.about.sub":
    "Pas une liste de fonctionnalités conçue pour un pitch — un ensemble de problèmes qu'une enseignante a réellement vécus, résolus un par un.",
  "web.about.whoBuiltIt": "Qui l'a créée",
  "web.about.founders.jay.role": "Fondateur — le développeur",
  "web.about.founders.jay.bio":
    "Développeur. Il a créé SpiralClass pour le problème réel d'une professeure en exercice, pas pour une idée abstraite — c'est pourquoi chaque fonctionnalité existe pour une raison : quelqu'un en a eu besoin d'abord.",
  "web.about.ourWhy.title": "Notre raison d'être",
  "web.about.ourWhy.body":
    "Les enseignants indépendants font le plus dur — bien enseigner — puis perdent des heures à gérer leur agenda, à courir après les paiements et à se répéter sur WhatsApp. SpiralClass existe pour que l'administratif ne coûte jamais un cours à un enseignant, ni une leçon à un élève.",
  "web.about.whyTrust": "Pourquoi vous pouvez lui faire confiance",
  "web.about.trust.stripe.title": "Paiements traités par Stripe",
  "web.about.trust.stripe.body":
    "SpiralClass ne stocke jamais les données de votre carte. Les paiements passent par Stripe, le même processeur utilisé par Amazon et des millions d'entreprises dans le monde.",
  "web.about.trust.dataProtected.title": "Vos données, protégées",
  "web.about.trust.dataProtected.body":
    "Chiffrement en transit, accès restreint et un avis de confidentialité en langage clair sur ce que nous conservons et pourquoi.",
  "web.about.trust.realTeacher.title": "Construit avec une vraie enseignante",
  "web.about.trust.realTeacher.body":
    "Chaque fonctionnalité a été testée dans les cours réels d'une professeure en activité avant d'arriver à quiconque.",
  "web.about.trust.globalPay.title": "Soyez payé où que vous soyez",
  "web.about.trust.globalPay.body":
    "Par carte via Stripe là où c'est disponible, ou par virement bancaire direct via Wise partout ailleurs — il y a toujours un moyen d'être payé.",
  "web.about.trust.openSource.title": "Open source",
  "web.about.trust.openSource.body":
    "Toute la plateforme est publique sur GitHub sous licence {licence} — n'importe qui peut lire exactement comment les cours, les données de vos élèves et les paiements sont traités.",
  "web.about.trust.openSource.link": "Voir le code sur GitHub",
  "web.about.seeFeatures": "Voir les fonctionnalités",
  "web.trialBand.title": "Commencez votre essai gratuit de 30 jours.",
  "web.trialBand.noCard": "Aucune carte bancaire requise.",
  "web.trialBand.createAccount": "Créer un compte gratuit",
  "web.features.meta.title": "Fonctionnalités",
  "web.features.meta.description":
    "Tout ce que SpiralClass fait pour les enseignants de n'importe quelle matière.",
  "web.features.headline": "Tout ce dont vous avez besoin pour enseigner",
  "web.features.sub":
    "SpiralClass s'occupe de l'administratif pour que vous puissiez vous concentrer sur l'enseignement — quelle que soit la matière que vous enseignez.",
  "web.features.item.booking.title": "Page de réservation publique",
  "web.features.item.booking.body":
    "Un seul lien que vous partagez sur WhatsApp. Les élèves voient vos disponibilités, réservent et paient — sans effort supplémentaire de votre part.",
  "web.features.item.calendar.title": "Agenda avec vues jour, semaine et mois",
  "web.features.item.calendar.body":
    "Voyez vos cours dans le format que vous préférez. Ne confondez plus jamais les horaires et ne manquez plus une réservation.",
  "web.features.item.getPaid.title": "Soyez payé sans courir après",
  "web.features.item.getPaid.body":
    "Forfaits prépayés par carte (Stripe) ou Wise. L'argent arrive avant le cours — pas après.",
  "web.features.item.globalPay.title": "Paiements flexibles, dans tous les pays",
  "web.features.item.globalPay.body":
    "Carte via Stripe là où c'est pris en charge, ou virement bancaire direct via Wise partout ailleurs. Vous choisissez le mode — vos élèves peuvent toujours vous payer.",
  "web.features.item.reminders.title": "Rappels automatiques",
  "web.features.item.reminders.body":
    "Notification push et e-mail à 24 heures, 1 heure et 15 minutes avant. Moins d'absences, zéro effort supplémentaire.",
  "web.features.item.chat.title": "Messagerie de cours intégrée",
  "web.features.item.chat.body":
    "Messages et vidéo directement dans le cours. Sans passer d'une application à l'autre — tout au même endroit.",
  "web.features.item.materials.title": "Supports programmés",
  "web.features.item.materials.body":
    "Téléversez des fichiers ou collez des liens. Choisissez quand les envoyer — à la confirmation, 5 jours avant ou 1 heure avant.",
  "web.features.item.library.title": "Bibliothèque de supports par niveau",
  "web.features.item.library.body":
    "Organisez vos ressources par niveau et attribuez-les à plusieurs élèves à la fois. Créez une fois, réutilisez toujours.",
  "web.features.item.notes.title": "Notes et progression par élève",
  "web.features.item.notes.body":
    "Un profil pour chaque élève avec ses notes, son historique de cours et ses supports attribués — le tout en un coup d'œil.",
  "web.features.item.pricing.title": "Forfaits et tarifs personnalisés",
  "web.features.item.pricing.body":
    "Définissez des forfaits de cours, des tarifs à la séance, et ajustez le tarif par élève quand vous en avez besoin.",
  "web.features.item.homeScreen.title": "Ajoutez-la à votre écran d'accueil",
  "web.features.item.homeScreen.body":
    "Installez SpiralClass depuis votre navigateur. Votre agenda et vos élèves toujours dans votre poche.",
  "web.features.item.videoLessons.title": "Salle de classe vidéo intégrée",
  "web.features.item.videoLessons.body":
    "Enseignez directement dans SpiralClass — pas de liens Zoom, pas d'application distincte. Vidéo, notes et supports sur le même écran.",
  "web.features.item.liveCaptions.title": "Sous-titres et traduction en direct",
  "web.features.item.liveCaptions.body":
    "Vous parlez espagnol et votre élève lit les sous-titres en anglais en temps réel. Activés d'un simple geste, jamais stockés.",
  "web.features.item.videoCoach.title": "Coach IA pour votre vidéo",
  "web.features.item.videoCoach.body":
    "Ajoutez une courte vidéo de présentation à votre page de réservation et recevez l'avis de l'IA : points forts, améliorations concrètes et impression générale, dans votre langue.",
  "web.features.item.srs.title": "Vocabulaire en répétition espacée",
  "web.features.item.srs.body":
    "Le vocabulaire de vos cours alimente un calendrier de répétition espacée (SM-2) qui le fait revenir juste avant qu'il ne soit oublié.",
