    "Ce que vous nous payez pour le logiciel : le prix ci-dessus, ou rien du tout sur la formule Gratuite. C'est le seul argent que SpiralClass reçoit de vous, et sur aucune formule nous ne prélevons de commission sur ce que vous gagnez en enseignant.",
  "web.pricing.fees.processorLabel": "Les frais de traitement de Stripe",
  "web.pricing.fees.processorBody":
    "Vos élèves vous paient directement. Un paiement effectué via Stripe arrive directement sur votre propre compte Stripe, et Stripe vous facture ses propres frais pour le traiter. Ces frais sont ceux de Stripe, pas les nôtres — Stripe en fixe le tarif selon votre pays et le moyen de paiement utilisé, et SpiralClass n'en reçoit aucune part. Cela vaut pour tous les moyens que Stripe propose au paiement, y compris les options locales de virement ou d'espèces qu'il peut montrer à votre élève, pas seulement les cartes.",
  "web.pricing.fees.transferLabel": "Wise",
  "web.pricing.fees.transferBody":
    "Votre élève transfère l'argent directement sur votre compte Wise. Il ne passe jamais par Stripe, il n'y a donc aucuns frais de traitement Stripe. Wise ou votre banque peuvent toutefois vous facturer la réception.",
  "web.pricing.fees.stripeLink": "Voir les tarifs de Stripe",
